// Schematic map data for the AI-Decides map panel (data/madrid-s1-map.json), scale 1.
//   node tools/build-map.mjs <dir with base-1-*.csv>       (GTFS-Scale-1-CHANGE, data/shared/, base version)
// GTFS-Madrid-Bench's stop_lat / stop_lon are GENERATED by the benchmark (integers 1..996, not degrees): they are kept
// as schematic x / y, never presented as Madrid geography. Trips are numbered exactly as build-data.mjs and
// ai-model.js build() do (ROUTES file order, then TRIPS file order, trips with an unknown route/service skipped), and
// each trip's stops are its STOP_TIMES rows in file order, so stop j of a trip is routes[r].trips[t].st[j]
// (stop_sequence is empty on some rows; file order is the order build() uses).
import { readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
const OUT = join(dirname(fileURLToPath(import.meta.url)), "..", "data", "madrid-s1-map.json");
const dir = process.argv[2];
const csv = (t) => { const [hd, ...rows] = readFileSync(join(dir, `base-1-${t}.csv`), "utf8").replace(/^\uFEFF/, "").trim().split(/\r?\n/);
  const k = hd.split(","); return rows.map((l) => { const v = l.split(","), o = {}; k.forEach((x, i) => (o[x] = v[i])); return o; }); };
const routes = csv("ROUTES"), trips = csv("TRIPS"), stops = csv("STOPS"), st = csv("STOP_TIMES"), cal = csv("CALENDAR");
const sIx = new Map(stops.map((s, i) => [s.stop_id, i])), rIx = new Map(routes.map((r, i) => [r.route_id, i])), svc = new Set(cal.map((c) => c.service_id));
const byTrip = new Map(); st.forEach((s) => { if (!byTrip.has(s.trip_id)) byTrip.set(s.trip_id, []); byTrip.get(s.trip_id).push(sIx.get(s.stop_id)); });
const R = routes.map(() => []);
trips.forEach((t) => { const r = rIx.get(t.route_id); if (r == null || !svc.has(t.service_id)) return; R[r].push(byTrip.get(t.trip_id) || []); });
const out = { v: 1, scale: 1, generated: true,
  note: "Schematic: stop_lat/stop_lon of GTFS-Madrid-Bench are generated by the benchmark (integers 1..996), not Madrid geography.",
  source: "GTFS-Madrid-Bench (Van Assche et al.), Zenodo 10.5281/zenodo.14038823, GTFS-Scale-1-CHANGE, base version: STOPS, STOP_TIMES, TRIPS, ROUTES",
  stops: stops.map((s) => [+s.stop_lon, +s.stop_lat]), routes: R };
writeFileSync(OUT, JSON.stringify(out));
console.log(OUT, stops.length, "stops", R.length, "routes", R.reduce((a, x) => a + x.length, 0), "trips", R.flat().reduce((a, x) => a + x.length, 0), "stop_times");
